import SwiftUI
import UIKit
import Vision

/// Preparation for the approved study: OCR of an image generated by this app.
/// Screen capture is opt-in through a separate system-prompt panel below.
/// Nothing inspects another app or calls a backend in this first-stage test.
@MainActor
struct CaptureStudyView: View {
    @Environment(\.scenePhase) private var scenePhase
    @State private var session = CaptureStudySession()
    @State private var status = "Synthetic self-test is idle."
    @State private var result = ""
    @State private var running = false
    @State private var work: Task<Void, Never>?
    @State private var expiration: Task<Void, Never>?

    private let fixture = "ALEX: Coffee on Saturday?\nME: Let me check my schedule."

    var body: some View {
        NavigationStack {
            Form {
                Section("Synthetic OCR check") {
                    Text("The synthetic OCR self-test reads an app-generated image. The system test below defaults to sharing this app. An optional wider-screen test uses an invented note, with explicit confirmation and system permission. No iMessage or Snapchat compatibility is established.")
                    Text("No audio, saved image, network request or AI generation.")
                }
                Section("Synthetic image text") {
                    Text(fixture).font(.body.monospaced())
                }
                Button("Run synthetic OCR self-test", action: run)
                    .disabled(running)
                Button("Stop and clear", role: .destructive, action: stop)
                Section("Synthetic OCR status") { Text(status) }
                if !result.isEmpty {
                    Section("Recognized text — expires within 30 seconds") { Text(result) }
                }
#if canImport(ScreenCaptureKit)
                if #available(iOS 27.0, *) {
                    ScreenCaptureStudyPanel()
                } else {
                    Section("System capture unavailable") { Text("This study adapter requires iOS 27 or later.") }
                }
#endif
                Section("Next gate") {
                    Text("A current-app frame was successfully read on the test phone. The next controlled Notes test probes cross-app delivery. Keyboard context transfer, Snapchat compatibility and real AI replies remain unimplemented.")
                }
            }
            .navigationTitle("Local capture study")
        }
        .onDisappear(perform: stop)
        .onChange(of: scenePhase) { _, phase in
            if phase != .active { stop() }
        }
    }

    private func run() {
        stop()
        // Only this fixed invented image is accepted by the self-test UI.
        let renderer = UIGraphicsImageRenderer(size: CGSize(width: 960, height: 220),
                                               format: imageFormat())
        let image = renderer.image { context in
            UIColor.white.setFill()
            context.fill(CGRect(x: 0, y: 0, width: 960, height: 220))
            (fixture as NSString).draw(in: CGRect(x: 24, y: 30, width: 912, height: 160),
                                      withAttributes: [.font: UIFont.systemFont(ofSize: 30),
                                                       .foregroundColor: UIColor.black])
        }
        guard let pixels = image.cgImage else {
            status = "Cannot construct the synthetic test image."
            return
        }
        let id = session.begin()
        guard let token = session.requestFrame() else { return }
        running = true
        status = "Recognizing the synthetic image locally…"
        work = Task { @MainActor in
            do {
                let text = try await recognize(pixels)
                guard !Task.isCancelled, session.sessionID == id else { return }
                let accepted = session.complete(token, text: text)
                result = session.currentText ?? ""
                status = accepted ? "Synthetic OCR finished. The test image was not saved or uploaded."
                                  : "The local result was expired or rejected."
            } catch {
                guard !Task.isCancelled, session.sessionID == id else { return }
                session.stop()
                result = ""
                status = "Local OCR failed. No text was uploaded or saved."
            }
            running = false
            work = nil
        }
        expiration = Task { @MainActor in
            do { try await Task.sleep(nanoseconds: 30_000_000_000) }
            catch { return }
            guard !Task.isCancelled else { return }
            work?.cancel()
            work = nil
            session.stop()
            result = ""
            running = false
            status = "Study expired; temporary text cleared."
        }
    }

    private func imageFormat() -> UIGraphicsImageRendererFormat {
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        return format
    }

    private func stop() {
        work?.cancel()
        expiration?.cancel()
        work = nil
        expiration = nil
        session.stop()
        result = ""
        running = false
        status = "Synthetic self-test stopped; temporary text cleared."
    }

    private func recognize(_ image: CGImage) async throws -> String {
        try await withCheckedThrowingContinuation { continuation in
            DispatchQueue.global(qos: .userInitiated).async {
                do {
                    let request = VNRecognizeTextRequest()
                    request.recognitionLevel = .accurate
                    request.recognitionLanguages = ["en-US"]
                    let handler = VNImageRequestHandler(cgImage: image, options: [:])
                    try handler.perform([request])
                    let text = (request.results ?? []).compactMap {
                        $0.topCandidates(1).first?.string
                    }.joined(separator: "\n")
                    continuation.resume(returning: text)
                } catch {
                    continuation.resume(throwing: error)
                }
            }
        }
    }
}
